// @FIGURE_CODE_BEGIN
var G = 9.8;
var C = { orange: '#ef6c33', purple: '#a03e9e', teal: '#199a96', ghost: '#c7cbd1', ghostBar: '#b2b7be', ink: '#333' };

var state = { speed: 30, angle: 45, comp: false };

function traj(v, thDeg, n) {
  n = n || 140;
  var r = thDeg * Math.PI / 180;
  var R = v * v * Math.sin(2 * r) / G;
  var H = v * v * Math.pow(Math.sin(r), 2) / (2 * G);
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var x = R * i / n;
    var y = x * Math.tan(r) - G * x * x / (2 * v * v * Math.cos(r) * Math.cos(r));
    pts.push({ x: x, y: Math.max(0, y) });
  }
  return { pts: pts, R: R, H: H, apexX: R / 2 };
}

function aEngaged() { return state.speed !== 30; }
function bEngaged() { return state.angle !== 45 || state.comp; }
function bucketA(v) { return v < 35 ? C.orange : (v < 45 ? C.purple : C.teal); }
function bucketB(a) { return a < 30 ? C.orange : (a < 60 ? C.purple : C.teal); }

/* ---------- canvas helpers ---------- */
function arrow(ctx, x0, y0, x1, y1, color, lw, hl) {
  var ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x0, y0);
  ctx.lineTo(x1 - Math.cos(ang) * hl * 0.55, y1 - Math.sin(ang) * hl * 0.55); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - Math.cos(ang - 0.38) * hl, y1 - Math.sin(ang - 0.38) * hl);
  ctx.lineTo(x1 - Math.cos(ang + 0.38) * hl, y1 - Math.sin(ang + 0.38) * hl);
  ctx.closePath(); ctx.fill();
}
function htext(ctx, t, x, y, color, fs, align, baseline) {
  ctx.font = fs.toFixed(1) + 'px sans-serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = baseline || 'middle';
  ctx.lineJoin = 'round';
