  ctx.strokeStyle = color; ctx.lineWidth = 1.1;
  ctx.beginPath(); ctx.moveTo(xa, yy - s); ctx.lineTo(xa, yy + s);
  ctx.moveTo(xb, yy - s); ctx.lineTo(xb, yy + s); ctx.stroke();
  var cx = (xa + xb) / 2;
  arrow(ctx, cx, yy, xa, yy, color, 1.1, fs * 0.62);
  arrow(ctx, cx, yy, xb, yy, color, 1.1, fs * 0.62);
  ctx.font = fs.toFixed(1) + 'px sans-serif';
  var w = ctx.measureText(label).width;
  ctx.fillStyle = '#fff';
  ctx.fillRect(cx - w / 2 - 4, yy - fs * 0.72, w + 8, fs * 1.44);
