function readoutBox(ctx, px, py, lines, color, fs, area) {
  ctx.font = fs.toFixed(1) + 'px sans-serif';
  var w = 0, i;
  for (i = 0; i < lines.length; i++) w = Math.max(w, ctx.measureText(lines[i]).width);
  var pad = fs * 0.5, bw = w + pad * 2, bh = lines.length * fs * 1.3 + pad * 1.6;
  var x = px + fs * 0.9, y = py - bh - fs * 0.7;
  if (x + bw > area.right - 2) x = px - bw - fs * 0.9;
  if (x < area.left + 2) x = area.left + 2;
  if (y < area.top + 2) y = area.top + 2;
  ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.strokeStyle = color; ctx.lineWidth = 1;
