  if (ctx.roundRect) { ctx.roundRect(x, y, bw, bh, 4); } else { ctx.rect(x, y, bw, bh); }
  ctx.fill(); ctx.stroke();
  ctx.textAlign = 'left'; ctx.textBaseline = 'top'; ctx.fillStyle = '#222';
  for (i = 0; i < lines.length; i++) ctx.fillText(lines[i], x + pad, y + pad * 0.8 + i * fs * 1.3);
