var A30 = traj(30, 45), A40 = traj(40, 45), A50 = traj(50, 45);
var B15 = traj(50, 15), B45 = traj(50, 45), B75 = traj(50, 75);

/* ---------- panel A drawing ---------- */
var pluginA = {
  id: 'panelA',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, area = chart.chartArea;
    var X = function (v) { return chart.scales.x.getPixelForValue(v); };
    var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
    var S = Math.min(area.right - area.left, area.bottom - area.top);
    var fs = Math.max(8, Math.min(13, S / 19));
    var g = aEngaged();
    var gc = g ? C.ghost : null;

    // ground
    ctx.strokeStyle = '#333'; ctx.lineWidth = 1.1;
    ctx.beginPath(); ctx.moveTo(X(-16), Y(0)); ctx.lineTo(X(284), Y(0)); ctx.stroke();

    // apex dashed lines of textbook curves
    var tb = [[A30, C.orange], [A40, C.purple], [A50, C.teal]];
    for (var i = 0; i < 3; i++) {
      dashLine(ctx, X(tb[i][0].apexX), Y(tb[i][0].H), X(tb[i][0].apexX), Y(0), g ? '#d9dce0' : '#9a9a9a', 1);
    }

    // launch arrows along 45deg ray
    var ox = X(0), oy = Y(0);
    var sp = [[30, C.orange, 0.30], [40, C.purple, 0.40], [50, C.teal, 0.50]];
    var c45 = Math.SQRT1_2;
    for (i = 0; i < 3; i++) {
      var L = S * sp[i][2];
      var tx = ox + L * c45, ty = oy - L * c45;
      var col = gc || sp[i][1];
      arrow(ctx, ox, oy, tx, ty, col, 1.8, fs * 0.8);
      htext(ctx, sp[i][0] + ' m/s', tx - fs * 0.6, ty - fs * 0.35, col, fs, 'right', 'middle');
    }
    // 45 deg arc
    arcAt(ctx, ox, oy, S * 0.17, 45, gc || '#444', 1);
    htext(ctx, '45°', ox + S * 0.17 * Math.cos(20 * Math.PI / 180) + fs * 0.4,
      oy - S * 0.17 * Math.sin(20 * Math.PI / 180) - fs * 0.1, gc || '#333', fs, 'left', 'middle');

    // dimension bars
    var bc = g ? C.ghostBar : '#333';
    dimBar(ctx, X(0), X(A30.R), Y(-14), 'R = 91.8 m', bc, fs);
    dimBar(ctx, X(0), X(A40.R), Y(-30), 'R = 163 m', bc, fs);
    dimBar(ctx, X(0), X(A50.R), Y(-46), 'R = 255 m', bc, fs);

    // active overlay
    if (g) {
      var t = traj(state.speed, 45), col2 = bucketA(state.speed);
      var L2 = S * (0.14 + state.speed / 60 * 0.38);
      arrow(ctx, ox, oy, ox + L2 * c45, oy - L2 * c45, col2, 2.6, fs * 0.9);
      dashLine(ctx, X(t.apexX), Y(t.H), X(t.apexX), Y(0), col2, 1.3);
      ctx.fillStyle = col2;
      ctx.beginPath(); ctx.arc(X(t.apexX), Y(t.H), Math.max(2.2, fs * 0.22), 0, 6.3); ctx.fill();
      dimBar(ctx, X(0), X(t.R), Y(-62), 'R = ' + t.R.toFixed(1) + ' m', col2, fs);
      readoutBox(ctx, X(t.apexX), Y(t.H), [
        'v₀ = ' + state.speed + ' m/s,  θ = 45°',
        'apex h = ' + t.H.toFixed(1) + ' m',
        'R = ' + t.R.toFixed(1) + ' m'
      ], col2, fs * 0.92, area);
    }

    // axis key (upper right)
    var kx = area.right - S * 0.16, ky = area.top + S * 0.30, kl = S * 0.17;
    arrow(ctx, kx, ky, kx, ky - kl, '#000', 1.4, fs * 0.65);
    arrow(ctx, kx, ky, kx + kl, ky, '#000', 1.4, fs * 0.65);
    htext(ctx, 'y', kx - fs * 0.15, ky - kl - fs * 0.75, '#000', fs, 'center', 'middle');
    htext(ctx, 'x', kx + kl + fs * 0.6, ky, '#000', fs, 'center', 'middle');

    htext(ctx, '(a)', (area.left + area.right) / 2, Y(-70), '#222', fs, 'center', 'middle');
  }
};

/* ---------- panel B drawing ---------- */
var pluginB = {
  id: 'panelB',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, area = chart.chartArea;
    var X = function (v) { return chart.scales.x.getPixelForValue(v); };
    var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
    var S = Math.min(area.right - area.left, area.bottom - area.top);
    var fs = Math.max(8, Math.min(13, S / 19));
    var g = bEngaged();
    var gc = g ? C.ghost : null;

    ctx.strokeStyle = '#333'; ctx.lineWidth = 1.1;
    ctx.beginPath(); ctx.moveTo(X(-16), Y(0)); ctx.lineTo(X(284), Y(0)); ctx.stroke();

    // textbook dashed guides: 75deg apex, shared 128 m landing
    dashLine(ctx, X(B75.apexX), Y(B75.H), X(B75.apexX), Y(0), g ? '#d9dce0' : '#9a9a9a', 1);
    dashLine(ctx, X(B15.R), Y(63.8), X(B15.R), Y(0), g ? '#d9dce0' : '#9a9a9a', 1);

    var ox = X(0), oy = Y(0);
    var angs = [[15, C.orange, 0.22], [45, C.purple, 0.30], [75, C.teal, 0.38]];
    var i, a, rad, col;
    for (i = 0; i < 3; i++) {
      a = angs[i][0]; rad = a * Math.PI / 180; col = gc || angs[i][1];
      var L = S * 0.34;
      var tx = ox + L * Math.cos(rad), ty = oy - L * Math.sin(rad);
      arrow(ctx, ox, oy, tx, ty, col, 1.8, fs * 0.8);
      arcAt(ctx, ox, oy, S * angs[i][2], a, gc || '#444', 1);
      var lr = S * angs[i][2] * 0.78, la = a * 0.45 * Math.PI / 180;
      htext(ctx, a + '°', ox + lr * Math.cos(la), oy - lr * Math.sin(la) - fs * 0.45,
        gc || '#333', fs, 'center', 'middle');
    }
    // v0 label beside steepest arrow
    var L75 = S * 0.34, r75 = 75 * Math.PI / 180;
    htext(ctx, 'v₀ = 50 m/s', ox + L75 * Math.cos(r75) - fs * 0.8, oy - L75 * Math.sin(r75) - fs * 0.9,
      gc || '#222', fs, 'right', 'middle');

    var bc = g ? C.ghostBar : '#333';
    dimBar(ctx, X(0), X(B15.R), Y(-14), 'R = 128 m', bc, fs);
    dimBar(ctx, X(0), X(B45.R), Y(-30), 'R = 255 m', bc, fs);

    if (g) {
      var t = traj(50, state.angle), col2 = bucketB(state.angle);
      var rr = state.angle * Math.PI / 180, LA = S * 0.34;
      arrow(ctx, ox, oy, ox + LA * Math.cos(rr), oy - LA * Math.sin(rr), col2, 2.6, fs * 0.9);
      dashLine(ctx, X(t.apexX), Y(t.H), X(t.apexX), Y(0), col2, 1.3);
      dashLine(ctx, X(t.R), Y(t.H * 0.5), X(t.R), Y(0), col2, 1.0);
      ctx.fillStyle = col2;
      ctx.beginPath(); ctx.arc(X(t.apexX), Y(t.H), Math.max(2.2, fs * 0.22), 0, 6.3); ctx.fill();
      dimBar(ctx, X(0), X(t.R), Y(-48), 'R = ' + t.R.toFixed(1) + ' m', col2, fs);
      readoutBox(ctx, X(t.apexX), Y(t.H), [
        'v₀ = 50 m/s,  θ = ' + state.angle + '°',
        'apex h = ' + t.H.toFixed(1) + ' m',
        'R = ' + t.R.toFixed(1) + ' m'
      ], col2, fs * 0.92, area);

      if (state.comp) {
        var ca = 90 - state.angle, tc = traj(50, ca);
        ctx.fillStyle = col2;
        ctx.beginPath(); ctx.arc(X(tc.apexX), Y(tc.H), Math.max(2.2, fs * 0.22), 0, 6.3); ctx.fill();
        dashLine(ctx, X(tc.apexX), Y(tc.H), X(tc.apexX), Y(0), col2, 1);
        htext(ctx, '90° − θ = ' + ca + '° · h = ' + tc.H.toFixed(1) + ' m',
          X(tc.apexX) + fs * 0.6, Y(tc.H) - fs * 0.9, col2, fs * 0.92, 'left', 'middle');
      }
    }

    htext(ctx, '(b)', (area.left + area.right) / 2, Y(-70), '#222', fs, 'center', 'middle');
  }
};

