/* ---------- control handlers ---------- */
function update_speedSlider(v) { state.speed = v; render(); }
function update_angleSlider(v) { state.angle = v; render(); }
function toggle_showComplement(on) { state.comp = on; render(); }
function showInsight() {
  showPopup('Why R = v₀² sin(2θ)/g',
    'Flight time is set by the vertical launch speed (t = 2v₀sinθ/g) and horizontal distance is that time times v₀cosθ. Multiplying gives R = v₀²·sin(2θ)/g: speed enters squared, so it dominates, while the angle enters only through sin(2θ). Since sin(2θ) peaks at θ = 45° and satisfies sin(2θ) = sin(2(90°−θ)), complementary angles produce identical ranges from very different-looking paths.');
}

/* ---------- hover / click ---------- */
function attachInteraction(chart, canvas) {
  function nearest(e) {
    var rect = canvas.getBoundingClientRect();
    var mx = e.clientX - rect.left, my = e.clientY - rect.top;
    var best = -1, bd = 14;
    chart.data.datasets.forEach(function (d, i) {
      if (!d.data || !d.data.length) return;
      for (var k = 0; k < d.data.length; k++) {
        var px = chart.scales.x.getPixelForValue(d.data[k].x);
        var py = chart.scales.y.getPixelForValue(d.data[k].y);
        var dd = Math.hypot(px - mx, py - my);
        if (dd < bd) { bd = dd; best = i; }
      }
    });
    return best;
  }
  canvas.addEventListener('mousemove', function (e) {
    var i = nearest(e);
    if (i >= 0) { canvas.style.cursor = 'pointer'; showTooltip(chart.data.datasets[i].tip || chart.data.datasets[i].label, e); }
    else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mouseleave', hideTooltip);
  canvas.addEventListener('click', function (e) {
    var i = nearest(e);
    if (i < 0) return;
    var d = chart.data.datasets[i];
    if (d.label === 'Your launch') {
      showPopup('Your trajectory', d.tip + '. Range comes from R = v₀²sin(2θ)/g and apex height from h = (v₀sinθ)²/2g. Change the sliders and watch which factor moves the landing point most.');
    } else if (d.label === 'Complementary angle') {
      showPopup('Complementary angle', d.tip + '. Because sin(2θ) = sin(180° − 2θ), the angle 90° − θ gives exactly the same range — but a much different apex height and flight time.');
    } else {
      showPopup('Textbook curve: ' + d.label, d.tip + '. These are the reference curves from the original figure; your interactive curve is drawn bold over them for comparison.');
    }
  });
}
attachInteraction(chartA, cvA);
attachInteraction(chartB, cvB);

